package au.monster.tracker;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.sqlite.SQLiteDatabase;
import java.util.*;

/** Tax choices are future-only. Exact historical costs derive from immutable FIFO ledger order. */
public final class FinanceStore {
    private final Store store;
    public FinanceStore(Store store){this.store=store;}
    static Map<String,Object> settings(SQLiteDatabase db){Map<String,Object> result=new LinkedHashMap<>();try(Cursor c=db.rawQuery("SELECT key,body FROM finance_settings ORDER BY key",null)){while(c.moveToNext())result.put(c.getString(0),Json.parse(c.getString(1)));}return result;}
    public Map<String,Object> settings(){synchronized(store){return settings(store.database());}}
    private static String treatment(SQLiteDatabase db,String product){var all=settings(db);Object value=all.get("product:"+product);return value==null?"taxable":Purchases.str(Purchases.map(value),"treatment");}
    static void plan(SQLiteDatabase db,Ledger.Event event,long actualGst){if(actualGst>event.cost())Purchases.bad("GST cannot exceed the purchase cost.");try(Cursor c=db.rawQuery("SELECT body FROM finance_tax_plans WHERE source_id=?",new String[]{event.id()})){if(c.moveToFirst())return;}var gst=Purchases.map(settings(db).get("gst"));boolean registered=FinanceBackup.bool(gst,"registered");String product=Catalog.LEGACY;try(Cursor c=db.rawQuery("SELECT body FROM catalog_plans WHERE event_id=?",new String[]{event.id()})){if(c.moveToFirst()){var a=Catalog.allocations(Json.parse(c.getString(0)));if(a.size()==1)product=a.get(0).productId();}}String mode=treatment(db,product);long output=registered&&mode.equals("taxable")&&(event.type().equals("single")||event.type().equals("deal"))?(event.revenue()+5)/11:0,input=registered&&!mode.equals("input_taxed")?actualGst:0;ContentValues v=new ContentValues();v.put("source_id",event.id());v.put("body",Json.write(FinanceBackup.taxMap(new Finance.Tax(registered,actualGst,input,output))));db.insertOrThrow("finance_tax_plans",null,v);}
    static void commit(SQLiteDatabase db,Ledger.Event event){plan(db,event,0);try(Cursor c=db.rawQuery("SELECT body FROM finance_tax_plans WHERE source_id=?",new String[]{event.id()})){if(c.moveToFirst()){ContentValues v=new ContentValues();v.put("source_id",event.id());v.put("kind","ledger");v.put("body",c.getString(0));db.insertOrThrow("finance_tax",null,v);}}db.delete("finance_tax_plans","source_id=?",new String[]{event.id()});}
    static void document(SQLiteDatabase db,Purchases.Document document){long gst=0;if(document.kind().equals("expense"))gst=document.gst();else for(var l:document.lines())if(!l.stock())gst+=l.gst();var settings=Purchases.map(settings(db).get("gst"));boolean registered=FinanceBackup.bool(settings,"registered");long input=registered&&FinanceBackup.bool(settings,"expenseCredits")?gst:0;ContentValues v=new ContentValues();v.put("source_id",document.id());v.put("kind","document");v.put("body",Json.write(FinanceBackup.taxMap(new Finance.Tax(registered,gst,input,0))));db.insertOrThrow("finance_tax",null,v);}
    static long receivedGst(SQLiteDatabase db,String lineId,Purchases.Line line){long sum=0;try(Cursor c=db.rawQuery("SELECT e.cost,t.body FROM deliveries d JOIN events e ON e.id=d.event_id LEFT JOIN finance_tax t ON t.source_id=e.id WHERE d.line_id=? AND NOT EXISTS(SELECT 1 FROM events u WHERE u.type='undo' AND u.target=e.id)",new String[]{lineId})){while(c.moveToNext())sum+=c.isNull(1)?(line.cost()==0?0:line.gst()*c.getLong(0)/line.cost()):FinanceBackup.tax(Json.parse(c.getString(1))).actualGst();}return sum;}
    public void saveSettings(boolean registered,boolean credits,Map<String,String> productModes){synchronized(store){SQLiteDatabase db=store.database();db.beginTransaction();try{Map<String,Object> data=new LinkedHashMap<>();Map<String,Object> gst=new LinkedHashMap<>();gst.put("registered",registered);gst.put("expenseCredits",credits);data.put("gst",gst);for(var e:productModes.entrySet())data.put("product:"+e.getKey(),Collections.singletonMap("treatment",e.getValue()));Set<String> ids=new HashSet<>();for(var p:new CatalogStore(store).view().products())ids.add(p.id());FinanceBackup.settings(data,ids);for(var e:data.entrySet()){ContentValues v=new ContentValues();v.put("key",e.getKey());v.put("body",Json.write(e.getValue()));db.insertWithOnConflict("finance_settings",null,v,SQLiteDatabase.CONFLICT_REPLACE);}audit(db,"finance.settings",data);db.setTransactionSuccessful();}finally{db.endTransaction();}}}
    private static void audit(SQLiteDatabase db,String action,Map<String,Object> data){ContentValues v=new ContentValues();long now=System.currentTimeMillis();v.put("id",Ledger.id());v.put("recorded_at",now);v.put("occurred_at",now);v.put("action",action);v.put("entity_id","finance-settings");v.put("payload",Json.write(data));db.insertOrThrow("audit",null,v);}
    public Finance.Result result(){synchronized(store){var snapshot=store.snapshot();var business=new BusinessStore(store).view();var catalog=new CatalogStore(store).export();Map<String,List<Catalog.Allocation>> allocations=new HashMap<>();for(Object value:Purchases.list(catalog.get("allocations"))){var m=Purchases.map(value);allocations.put(Purchases.str(m,"eventId"),Catalog.allocations(m.get("allocations")));}List<Catalog.Transfer> transfers=new ArrayList<>();for(Object value:Purchases.list(catalog.get("transfers")))transfers.add(Catalog.transfer(value));List<Purchases.Document> documents=business.documents();List<Map<String,Object>> cancellations=new ArrayList<>();try(Cursor c=store.database().rawQuery("SELECT body FROM document_cancellations ORDER BY rowid",null)){while(c.moveToNext())cancellations.add(Purchases.map(Json.parse(c.getString(0))));}Map<String,Finance.Tax> taxes=new HashMap<>();for(Object value:Purchases.list(export().get("taxes"))){var m=Purchases.map(value);taxes.put(Purchases.str(m,"id"),FinanceBackup.tax(m.get("tax")));}var refunds=new RefundStore(store);var result=Finance.calculate(snapshot.events(),allocations,transfers,documents,cancellations,taxes,refunds.returnSources());List<Finance.Row> financial=new ArrayList<>(result.rows());financial.addAll(refunds.financialRows(taxes));return new Finance.Result(Ledger.copy(financial),result.inventoryValue());}}
    public Map<String,Object> export(){synchronized(store){Map<String,Object> result=new LinkedHashMap<>();result.put("settings",settings(store.database()));List<Object> taxes=new ArrayList<>();try(Cursor c=store.database().rawQuery("SELECT source_id,kind,body FROM finance_tax ORDER BY rowid",null)){while(c.moveToNext()){Map<String,Object> row=new LinkedHashMap<>();row.put("id",c.getString(0));row.put("kind",c.getString(1));row.put("tax",Json.parse(c.getString(2)));taxes.add(row);}}result.put("taxes",taxes);return result;}}
    void restore(Map<String,Object> data){if(data==null)return;SQLiteDatabase db=store.database();for(Object value:Purchases.list(data.get("taxes"))){var row=Purchases.map(value);String id=Purchases.str(row,"id"),kind=Purchases.str(row,"kind"),body=Json.write(row.get("tax"));try(Cursor c=db.rawQuery("SELECT kind,body FROM finance_tax WHERE source_id=?",new String[]{id})){if(c.moveToFirst()){if(!kind.equals(c.getString(0))||!body.equals(c.getString(1)))Purchases.bad("Conflicting historical GST snapshot. Restore cancelled.");continue;}}ContentValues v=new ContentValues();v.put("source_id",id);v.put("kind",kind);v.put("body",body);db.insertOrThrow("finance_tax",null,v);}Map<String,Object> before=settings(db),after=Purchases.map(data.get("settings"));for(var e:after.entrySet()){ContentValues v=new ContentValues();v.put("key",e.getKey());v.put("body",Json.write(e.getValue()));db.insertWithOnConflict("finance_settings",null,v,SQLiteDatabase.CONFLICT_REPLACE);}if(!Json.write(before).equals(Json.write(after)))audit(db,"finance.settings_restore",after);}
}
